#[ORM\Entity] #[ORM\Table(name:'simulation_course',uniqueConstraints:[new ORM\UniqueConstraint(name:'uniq_simulation_course',columns:['simulation_id','course_id'])])] class SimulationCourse { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\ManyToOne(inversedBy:'courses')] #[ORM\JoinColumn(nullable:false)] private ?Simulation $simulation=null; #[ORM\ManyToOne(inversedBy:'simulations')] #[ORM\JoinColumn(nullable:false)] private ?Course $course=null; #[ORM\Column(length:30)] private string $statut='preparee'; #[ORM\Column(type:'datetime',nullable:true)] private ?\DateTimeInterface $dateDebut=null; #[ORM\Column(type:'datetime',nullable:true)] private ?\DateTimeInterface $dateFin=null; #[ORM\Column(length:500,nullable:true)] private ?string $fichierReplay=null; #[ORM\Column(length:500,nullable:true)] private ?string $telemetryPath=null; public function getId():?int{return $this->id;} public function getSimulation():?Simulation{return $this->simulation;} public function setSimulation(?Simulation $v):self{$this->simulation=$v;return $this;} public function getCourse():?Course{return $this->course;} public function setCourse(?Course $v):self{$this->course=$v;return $this;} public function getStatut():string{return $this->statut;} public function setStatut(string $v):self{$this->statut=$v;return $this;} public function getDateDebut():?\DateTimeInterface{return $this->dateDebut;} public function setDateDebut(?\DateTimeInterface $v):self{$this->dateDebut=$v;return $this;} public function getDateFin():?\DateTimeInterface{return $this->dateFin;} public function setDateFin(?\DateTimeInterface $v):self{$this->dateFin=$v;return $this;} public function getFichierReplay():?string{return $this->fichierReplay;} public function setFichierReplay(?string $v):self{$this->fichierReplay=$v;return $this;} public function getTelemetryPath():?string{return $this->telemetryPath;} public function setTelemetryPath(?string $v):self{$this->telemetryPath=$v;return $this;} }
